function rotateArray(a, k) {
  const n = a.length;
  k %= n;
  const reverse = (lo, hi) => {
    while (lo < hi) {
      [a[lo], a[hi]] = [a[hi], a[lo]];
      lo++;
      hi--;
    }
  };
  reverse(0, n - 1);
  reverse(0, k - 1);
  reverse(k, n - 1);
  return a;
}

console.log(rotateArray([1, 2, 3, 4, 5, 6, 7], 3));

