void rev(int a[], int l, int r) {
    while (l<r) {
        int t=a[l];
        a[l++]=a[r];
        a[r--]=t;
    }
}
void rotate(int a[], int n, int k) {
    k%=n;
    rev(a, 0, n-1);
    rev(a, 0, k-1);
    rev(a, k, n-1);
}
